/**
 * @file 用户管理字段配置
 * @domain pages/system/user
 * @description 定义用户查询表单、表格列和编辑表单字段，供配置化 CRUD 组件渲染。
 */

import type { UserInfo } from '@/entities/user'
import type { ConfigFieldOption, ConfigFormField, ConfigTableColumn, Translate } from '@/shared/config-crud'
import { createEnabledStatusOptions, createEnabledStatusSearchOptions, formatDateTime, getEnabledStatusTag, getStatusText } from '@/shared/lib/admin-display'

export function createUserSearchFields(t: Translate) {
  return [
    {
      prop: 'username',
      label: t('user.username'),
      type: 'input',
      placeholder: t('user.usernamePlaceholder'),
    },
    {
      prop: 'role',
      label: t('user.role'),
      type: 'select',
      placeholder: t('user.role'),
      options: [
        {
          label: t('common.admin'),
          value: 'admin',
        },
        {
          label: t('common.user'),
          value: 'user',
        },
      ],
    },
    {
      prop: 'status',
      label: t('user.status'),
      type: 'select',
      placeholder: t('user.status'),
      options: createEnabledStatusSearchOptions(getStatusText(t)),
    },
  ] satisfies ConfigFormField[]
}

export function createUserTableColumns(t: Translate) {
  return [
    {
      prop: 'id',
      label: 'ID',
      width: 80,
    },
    {
      prop: 'username',
      label: t('user.username'),
      minWidth: 120,
    },
    {
      label: t('user.role'),
      width: 130,
      tag: row => row.role === 'admin'
        ? {
            label: t('common.admin'),
            type: 'danger' as const,
          }
        : {
            label: t('common.user'),
            type: 'info' as const,
          },
    },
    {
      prop: 'email',
      label: t('user.email'),
      minWidth: 180,
    },
    {
      prop: 'phone',
      label: t('user.phone'),
      minWidth: 140,
    },
    {
      label: t('user.status'),
      width: 100,
      tag: row => getEnabledStatusTag(row.status, getStatusText(t)),
    },
    {
      label: t('user.createdAt'),
      minWidth: 180,
      formatter: row => formatDateTime(row.createdAt),
    },
  ] satisfies ConfigTableColumn<UserInfo>[]
}

export function createUserFormFields(t: Translate, options: {
  isEdit: boolean
  permissionOptions: ConfigFieldOption[]
  tenantOptions: ConfigFieldOption[]
  shopOptions: ConfigFieldOption[]
}) {
  const { isEdit, permissionOptions, tenantOptions, shopOptions } = options
  return [
    {
      prop: 'username',
      label: t('user.username'),
      type: 'input',
      placeholder: t('user.usernamePlaceholder'),
    },
    ...(!isEdit
      ? [{
          prop: 'password',
          label: t('login.password'),
          type: 'password' as const,
          placeholder: t('user.passwordPlaceholder'),
          showPassword: true,
        }]
      : []),
    {
      prop: 'role',
      label: t('user.role'),
      type: 'radio',
      options: [
        {
          label: t('common.admin'),
          value: 'admin',
        },
        {
          label: t('common.user'),
          value: 'user',
        },
      ],
    },
    {
      prop: 'dataScope',
      label: '数据范围',
      type: 'select',
      placeholder: '请选择数据范围',
      options: [
        {
          label: '全部（平台管理员）',
          value: 'ALL',
        },
        {
          label: '租户',
          value: 'TENANT',
        },
        {
          label: '店铺',
          value: 'SHOP',
        },
      ],
    },
    {
      prop: 'tenantId',
      label: '所属租户',
      type: 'select',
      placeholder: '请选择租户',
      filterable: true,
      options: tenantOptions,
      showWhen: (model: Record<string, unknown>) => model.dataScope !== 'ALL',
    },
    {
      prop: 'boundShopIds',
      label: '绑定店铺',
      type: 'select',
      placeholder: '请选择绑定店铺',
      multiple: true,
      filterable: true,
      collapseTags: true,
      collapseTagsTooltip: true,
      options: shopOptions,
      showWhen: (model: Record<string, unknown>) => model.dataScope === 'SHOP',
    },
    {
      prop: 'status',
      label: t('user.status'),
      type: 'radio',
      options: createEnabledStatusOptions(getStatusText(t)),
    },
    {
      prop: 'email',
      label: t('user.email'),
      type: 'input',
      placeholder: t('user.emailPlaceholder'),
    },
    {
      prop: 'phone',
      label: t('user.phone'),
      type: 'input',
      placeholder: t('user.phonePlaceholder'),
    },
    {
      prop: 'permissions',
      label: t('user.permissions'),
      type: 'select',
      placeholder: t('user.permissionsPlaceholder'),
      multiple: true,
      filterable: true,
      collapseTags: true,
      collapseTagsTooltip: true,
      options: permissionOptions,
    },
  ] satisfies ConfigFormField[]
}

/**
 * @file 用户管理组合式状态
 * @domain pages/system/user
 * @description 装配用户 CRUD、表单选项和自删除保护，表单校验由用户弹窗维护。
 */

import type { UserFormState } from './payload'
import type { CreateUserParams, UserInfo, UserListQuery } from '@/entities/user'
import { ElMessage } from 'element-plus'
import { getButtonPermissions } from '@/entities/permission'
import { useAuthStore } from '@/entities/session'
import { getTenantList } from '@/entities/tenant'
import { createUser, deleteUser, getUserList, updateUser } from '@/entities/user'
import { adminEndpoints } from '@/shared/api/endpoints'
import request from '@/shared/api/request'
import { useConfigCrud } from '@/shared/config-crud'
import { toUserPayload } from './payload'

/**
 * @description 有副作用：调用用户和权限接口，维护表格/表单状态，并在删除当前用户时触发 Element Plus 警告。
 * @returns 用户管理页面使用的 CRUD 状态、表单选项和操作函数。
 */
export function useUserManagement() {
  const { t } = useI18n()
  const authStore = useAuthStore()
  const permissionOptions = ref<{
    label: string
    value: string
  }[]>([])
  const tenantOptions = ref<{
    label: string
    value: number
  }[]>([])
  const shopOptions = ref<{
    label: string
    value: string
  }[]>([])

  const crud = useConfigCrud<UserInfo, UserListQuery, UserFormState, number>({
    getDefaultQuery: () => ({
      username: '',
      role: '' as UserListQuery['role'],
      status: '' as UserListQuery['status'],
    }),
    getDefaultForm: () => ({
      username: '',
      password: '',
      email: '',
      phone: '',
      role: 'user',
      status: 'ACTIVE',
      permissions: [],
      tenantId: null,
      dataScope: 'ALL',
      boundShopIds: [],
      _userId: undefined,
    }),
    fetchList: async () => {
      const list = await getUserList()
      return list.sort((a, b) => {
        if (a.role === 'admin' && b.role !== 'admin')
          return -1
        if (a.role !== 'admin' && b.role === 'admin')
          return 1
        return a.id - b.id
      })
    },
    createItem: payload => createUser(payload as CreateUserParams),
    updateItem: updateUser,
    deleteItem: deleteUser,
    getFormId: form => form._userId,
    getRowId: row => row.id,
    filterItem: (item, query) => {
      const usernameMatched = !query.username || item.username.includes(query.username)
      const roleMatched = !query.role || item.role === query.role
      const statusMatched = query.status === '' || String(item.status) === query.status
      return usernameMatched && roleMatched && statusMatched
    },
    toForm: row => ({
      username: row.username,
      password: '',
      email: row.email || '',
      phone: row.phone || '',
      role: row.role,
      status: row.status,
      permissions: [...row.permissions],
      tenantId: row.tenant?.id ?? null,
      dataScope: row.dataScope || 'ALL',
      boundShopIds: [...(row.boundShopIds || [])],
      _userId: row.id,
    }),
    toPayload: toUserPayload,
    deleteConfirm: row => t('user.deleteConfirm', { name: row.username }),
    saveSuccessMessage: ({ isEdit }) => t(isEdit ? 'user.updateSuccess' : 'user.createSuccess'),
    deleteSuccessMessage: t('user.deleteSuccess'),
  })

  function isSelf(row: UserInfo) {
    return row.id === authStore.userInfo?.id
  }

  async function handleDelete(row: UserInfo) {
    if (isSelf(row)) {
      ElMessage.warning(t('user.cannotDeleteSelf'))
      return
    }
    await crud.handleDelete(row)
  }

  async function fetchPermissionOptions() {
    const buttons = await getButtonPermissions().catch(() => [])
    permissionOptions.value = buttons.map(item => ({
      label: `${item.name}（${item.code}）`,
      value: item.code,
    }))
  }

  async function fetchTenantOptions() {
    const tenants = await getTenantList().catch(() => [])
    tenantOptions.value = tenants.map(t => ({
      label: `${t.name}（${t.code}）`,
      value: t.id,
    }))
  }

  async function fetchShopOptions() {
    interface ShopItem {
      id: number
      name: string
    }
    const restaurants = await request.get<ShopItem[]>(adminEndpoints.commerce.restaurants).catch(() => [])
    shopOptions.value = restaurants.map(r => ({
      label: r.name,
      value: String(r.id),
    }))
  }

  return {
    loading: crud.loading,
    saving: crud.saving,
    dialogVisible: crud.dialogVisible,
    query: crud.query,
    form: crud.form,
    isEdit: crud.isEdit,
    filteredData: crud.filteredData,
    resetQuery: crud.resetQuery,
    openCreateDialog: crud.openCreateDialog,
    openEditDialog: crud.openEditDialog,
    submitForm: crud.submitForm,
    permissionOptions,
    tenantOptions,
    shopOptions,
    isSelf,
    handleDelete,
    fetchUsers: crud.fetchRows,
    fetchPermissionOptions,
    fetchTenantOptions,
    fetchShopOptions,
  }
}

import type { CreateUserParams, UpdateUserParams } from '@/entities/user'
import type { AccountStatus } from '@/shared/lib/admin-display'

export interface UserFormState {
  username: string
  password: string
  email: string
  phone: string
  role: 'admin' | 'user'
  status: AccountStatus
  permissions: string[]
  tenantId: number | null
  dataScope: string
  boundShopIds: string[]
  _userId?: number
}

function normalizeCreateOptionalText(value?: string) {
  const text = value?.trim()
  return text || undefined
}

function normalizeUpdateOptionalText(value?: string) {
  const text = value?.trim()
  return text || null
}

export function toUserPayload(form: UserFormState): CreateUserParams | UpdateUserParams {
  const { _userId, password, email, phone, tenantId, dataScope, boundShopIds, ...rest } = form

  const tenantFields = {
    tenantId: dataScope === 'ALL' ? null : tenantId,
    dataScope,
    boundShopIds: dataScope === 'SHOP' ? boundShopIds : [],
  }

  if (_userId) {
    return {
      ...rest,
      ...tenantFields,
      email: normalizeUpdateOptionalText(email),
      phone: normalizeUpdateOptionalText(phone),
    }
  }

  return {
    ...rest,
    ...tenantFields,
    password,
    email: normalizeCreateOptionalText(email),
    phone: normalizeCreateOptionalText(phone),
  }
}

import type { UserFormState } from '../payload'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { computed, effectScope, ref } from 'vue'
import { toUserPayload } from '../payload'
import { useUserManagement } from '../useUserManagement'

const userApi = vi.hoisted(() => ({
  createUser: vi.fn(),
  deleteUser: vi.fn(),
  getUserList: vi.fn(),
  updateUser: vi.fn(),
}))

const permissionApi = vi.hoisted(() => ({
  getButtonPermissions: vi.fn(),
}))

vi.mock('element-plus', () => ({
  ElMessage: {
    warning: vi.fn(),
    success: vi.fn(),
  },
  ElMessageBox: {
    confirm: vi.fn(),
  },
}))

vi.mock('vue-i18n', () => ({
  useI18n: () => ({
    t: (key: string) => key,
  }),
}))

vi.mock('@/entities/user', () => userApi)

vi.mock('@/entities/permission', () => permissionApi)

vi.mock('@/entities/session', () => ({
  useAuthStore: () => ({
    userInfo: { id: 99 },
  }),
}))

vi.mock('@/shared/config-crud', async () => {
  const actual = await vi.importActual<typeof import('@/shared/config-crud/model/useConfigCrud')>('@/shared/config-crud/model/useConfigCrud')
  return actual
})

function createForm(overrides: Partial<UserFormState> = {}): UserFormState {
  return {
    username: 'alice',
    password: '123456',
    email: '',
    phone: '',
    role: 'user',
    status: 'ACTIVE',
    permissions: [],
    tenantId: null,
    dataScope: 'ALL',
    boundShopIds: [],
    ...overrides,
  }
}

function runInScope<T>(factory: () => T) {
  const scope = effectScope()
  const result = scope.run(factory)
  if (!result)
    throw new Error('effect scope did not return a result')
  return {
    result,
    dispose: () => scope.stop(),
  }
}

beforeEach(() => {
  vi.clearAllMocks()
  vi.stubGlobal('computed', computed)
  vi.stubGlobal('ref', ref)
  vi.stubGlobal('useI18n', () => ({
    t: (key: string) => key,
  }))
  userApi.createUser.mockResolvedValue(undefined)
  userApi.deleteUser.mockResolvedValue(undefined)
  userApi.getUserList.mockResolvedValue([])
  userApi.updateUser.mockResolvedValue(undefined)
  permissionApi.getButtonPermissions.mockResolvedValue([])
})

afterEach(() => {
  vi.restoreAllMocks()
  vi.unstubAllGlobals()
})

describe('toUserPayload', () => {
  it('keeps the password when creating a user', () => {
    const payload = toUserPayload(createForm())

    expect(payload).toMatchObject({
      username: 'alice',
      password: '123456',
      role: 'user',
      status: 'ACTIVE',
      permissions: [],
    })
    expect(payload).not.toHaveProperty('_userId')
  })

  it('drops the password when updating a user', () => {
    const payload = toUserPayload(createForm({
      _userId: 1,
      password: 'ignored',
    }))

    expect(payload).not.toHaveProperty('password')
    expect(payload).not.toHaveProperty('_userId')
  })

  it('normalizes empty optional contact fields for create and update payloads', () => {
    const createPayload = toUserPayload(createForm())
    const updatePayload = toUserPayload(createForm({ _userId: 1 }))

    expect(createPayload.email).toBeUndefined()
    expect(createPayload.phone).toBeUndefined()
    expect(updatePayload.email).toBeNull()
    expect(updatePayload.phone).toBeNull()
  })

  it('trims optional contact fields without changing password behavior', () => {
    const createPayload = toUserPayload(createForm({
      password: ' 123456 ',
      email: ' alice@example.com ',
      phone: ' 13800138000 ',
    }))
    const updatePayload = toUserPayload(createForm({
      _userId: 1,
      password: 'ignored',
      email: ' bob@example.com ',
      phone: ' 13900139000 ',
    }))

    expect(createPayload).toMatchObject({
      password: ' 123456 ',
      email: 'alice@example.com',
      phone: '13800138000',
    })
    expect(updatePayload).not.toHaveProperty('password')
    expect(updatePayload).toMatchObject({
      email: 'bob@example.com',
      phone: '13900139000',
    })
  })
})

describe('useUserManagement save payloads', () => {
  it('clears edit identity when opening create after editing', async () => {
    const { result: userManagement, dispose } = runInScope(() => useUserManagement())

    try {
      userManagement.openEditDialog({
        id: 7,
        username: 'alice',
        email: 'old@example.com',
        phone: '13800138000',
        avatar: null,
        role: 'admin',
        status: 'ACTIVE',
        permissions: ['user:view'],
        createdAt: '2026-05-22T00:00:00.000Z',
        updatedAt: '2026-05-22T00:00:00.000Z',
      })

      userManagement.openCreateDialog()

      expect(userManagement.isEdit.value).toBe(false)

      Object.assign(userManagement.form, {
        username: 'bob',
        password: '123456',
      })

      await userManagement.submitForm()

      expect(userApi.createUser).toHaveBeenCalledWith({
        username: 'bob',
        password: '123456',
        email: undefined,
        phone: undefined,
        role: 'user',
        status: 'ACTIVE',
        permissions: [],
        tenantId: null,
        dataScope: 'ALL',
        boundShopIds: [],
      })
      expect(userApi.updateUser).not.toHaveBeenCalled()
    }
    finally {
      dispose()
    }
  })

  it('creates users with password and omits blank optional contact fields', async () => {
    const { result: userManagement, dispose } = runInScope(() => useUserManagement())

    try {
      userManagement.openCreateDialog()
      Object.assign(userManagement.form, {
        username: 'alice',
        password: '123456',
        email: ' ',
        phone: '',
      })

      await userManagement.submitForm()

      expect(userApi.createUser).toHaveBeenCalledWith({
        username: 'alice',
        password: '123456',
        email: undefined,
        phone: undefined,
        role: 'user',
        status: 'ACTIVE',
        permissions: [],
        tenantId: null,
        dataScope: 'ALL',
        boundShopIds: [],
      })
      expect(userApi.updateUser).not.toHaveBeenCalled()
    }
    finally {
      dispose()
    }
  })

  it('updates users without password and clears blank optional contact fields', async () => {
    const { result: userManagement, dispose } = runInScope(() => useUserManagement())

    try {
      userManagement.openEditDialog({
        id: 7,
        username: 'alice',
        email: 'old@example.com',
        phone: '13800138000',
        avatar: null,
        role: 'admin',
        status: 'ACTIVE',
        permissions: ['user:view'],
        createdAt: '2026-05-22T00:00:00.000Z',
        updatedAt: '2026-05-22T00:00:00.000Z',
      })
      Object.assign(userManagement.form, {
        password: 'should-not-be-sent',
        email: '',
        phone: ' ',
      })

      await userManagement.submitForm()

      expect(userApi.createUser).not.toHaveBeenCalled()
      expect(userApi.updateUser).toHaveBeenCalledWith(7, {
        username: 'alice',
        email: null,
        phone: null,
        role: 'admin',
        status: 'ACTIVE',
        permissions: ['user:view'],
        tenantId: null,
        dataScope: 'ALL',
        boundShopIds: [],
      })
    }
    finally {
      dispose()
    }
  })
})

